function render(){if(!S.user){renderLogin();return}document.body.classList.remove('at-login');document.body.classList.toggle('demo-mode',DEMO);document.body.classList.toggle('compact',S.compact);const student=isFamily();const nav=accessibleNav();$('#app').innerHTML=`<aside class="sidebar"><div class="logo">${mark}<div><strong>${esc(loginDesign.academy_name||C.BRAND||'미래탐구')}</strong><small>CLASSROOM</small></div></div><div class="nav-label">${student?'MY CLASSROOM':'WORKSPACE'}</div><nav>${nav.map(([k,label,ic],i)=>`${k==='accounts'?'<div class="nav-label">ADMINISTRATION</div>':''}<button class="nav-item ${S.view===k?'active':''}" data-action="navigate" data-view="${k}">${icon(ic)}<span>${label}</span>${k==='consultations'&&S.data.consultations.filter(x=>x.status==='requested').length?`<span class="count">${S.data.consultations.filter(x=>x.status==='requested').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="flex"><span class="avatar">${esc(S.user.name?.slice(-2))}</span><div class="person grow"><strong>${esc(S.user.name)}</strong><small class="muted">${student?'학부모 · 가족 계정':S.user.role==='admin'?'최종관리자':'강사'}</small></div>${ib('edit','account-settings','','계정 설정')}${ib('logout','logout','','로그아웃')}</div></div></aside><div class="workspace"><header class="topbar"><div class="flex">${btn('', 'mobile-menu','','ghost icon mobile-toggle','menu')}<span class="breadcrumb">클래스룸 ${icon('chevron',11)} <strong>${titleFor(S.view)}</strong></span></div><div class="flex topbar-right" style="gap:20px">${student&&familyChildren().length>1?`<select id="family-student-select" class="input family-select" aria-label="학생 선택">${familyChildren().map(x=>`<option value="${x.id}" ${x.id===childID()?'selected':''}>${esc(x.name)} · ${esc(x.grade||x.school||x.student_no)}</option>`).join('')}</select>`:''}<button class="search-trigger" data-action="command">${icon('search',14)}<span class="grow">빠른 검색</span><kbd class="key">Ctrl K</kbd></button><span class="time-block date-label">${icon('calendar',13)} ${dateText(today(),true)}</span>${!student&&canUsePC()?btn('PC 확인 중','pc-pair','id="pc-header-button"','ghost sm'):""}${ib('refresh','refresh','id="refresh-button"','새로고침')}${ib('edit','account-settings','','계정 설정')}<span class="avatar">${esc(S.user.name?.slice(-2))}</span></div></header><main class="main" id="main"></main></div>${DEMO?`<div class="demo-banner"><span>미리보기 · 예시 데이터 · 실제 저장 안 됨</span><select id="demo-role" aria-label="미리보기 권한"><option value="admin" ${S.user.role==='admin'?'selected':''}>최종관리자</option><option value="teacher" ${S.user.role==='teacher'?'selected':''}>강사</option><option value="student" ${student?'selected':''}>학생 · 학부모</option></select></div>`:''}`;renderPage();updatePCIndicator();startPresence()}
function head(title,subtitle='',actions=''){return`<div class="page-head"><div><div class="eyebrow">${isFamily()?'MY LEARNING SPACE':'MIRAE CLASSROOM'}</div><h1>${title}</h1>${subtitle?`<p class="subtitle">${esc(subtitle)}</p>`:''}</div><div class="page-actions">${actions}</div></div>`}
function context({date=true,view=true}={}){return`<div class="contextbar"><select id="class-filter" class="input class-picker" style="max-width:390px" aria-label="수강반 선택">${classOptions(!isFamily()).map(([v,n])=>`<option value="${v}" ${S.classId===v?'selected':''}>${esc(n)}</option>`).join('')}</select>${date?`<div class="date-range"><input type="date" class="input small" id="date-start" value="${S.start}" aria-label="조회 시작일">—<input type="date" class="input small" id="date-end" value="${S.end}" aria-label="조회 종료일"></div>`:''}<span class="grow"></span>${view?`<div class="segmented"><button class="${S.mode==='table'?'active':''}" data-action="view-mode" data-mode="table">${icon('grid',13)} 표</button><button class="${S.mode==='list'?'active':''}" data-action="view-mode" data-mode="list">${icon('list',13)} 목록</button></div>`:''}</div>`}
