function section(title,content,action=''){return`<section class="section"><div class="section-heading"><h2>${title}</h2>${action}</div>${content}</section>`}
function renderPage(){const main=$('#main');if(!main)return;const student=isFamily();if(S.view==='dashboard'){renderDashboard();return}if(S.view==='settings'){renderSettings();return}if(S.view==='appearance'){renderLoginSettings();return}if(S.view==='reports'){renderReports();return}const descriptions={parents:'학부모 계정 하나로 형제·쌍둥이의 수강 기록을 함께 확인합니다.',students:'학생 정보와 수강 이력을 한곳에서 관리합니다.',classes:student?'지금 듣는 수업부터 지난 수업까지.':'반의 개강 · 종강 일정과 담당 강사를 관리합니다.',lessons:student?'수업 내용과 과제, 선생님의 코멘트입니다.':'날짜별 진도 · 과제 · 공지 · 학생 코멘트를 기록합니다.',exams:student?'쌓이는 기록 속에서 나의 변화를 확인하세요.':'시험별 점수를 입력하고 학습 흐름을 확인합니다.',homework:student?'과제를 제출하고 선생님의 확인 결과를 확인하세요.':'제출 사진과 미제출 학생을 한눈에 확인합니다.',consultations:student?'궁금한 점을 남겨 주시면 선생님이 확인합니다.':'상담 신청부터 일정 · 결과까지 관리합니다.',videos:'다시 보고 싶은 수업을 이어서 학습하세요.',accounts:'강사 계정과 재직 상태, 접근 권한을 관리합니다.',audit:'최근 500건의 데이터 변경 기록입니다.'};let actions='';if(!student){if(['parents','students','classes','lessons','exams','videos','accounts'].includes(S.view))actions+=btn(S.view==='parents'?'학부모 등록':S.view==='students'?'학생 등록':S.view==='classes'?'반 만들기':S.view==='lessons'?'수업 입력':S.view==='exams'?'시험 만들기':S.view==='videos'?'영상 등록':'강사 등록','new','','primary','plus');if(S.view==='students')actions+=btn(`타임넷에서 학생 목록 불러오기 <span class="muted" id="cache-age">· ${age(S.base.timenet_meta?.updated_at)}</span>`,'timenet-refresh','','','refresh');if(['students','classes','exams','videos'].includes(S.view))actions+=btn('일괄 입력','import','','','grid');}else if(S.view==='consultations')actions+=btn('상담 신청','new-consult','','primary','plus');main.innerHTML=head(titleFor(S.view),descriptions[S.view],actions)+(!['parents','accounts','audit'].includes(S.view)?context({date:!['students','classes','consultations'].includes(S.view)}):'')+`<div id="grid-zone"></div>`;renderGridZone()}
function renderDashboard(){const student=isFamily(),hw=expectedHomework(),now=new Date();if(student&&!familyChildren().length){$('#main').innerHTML=head('나의 클래스룸')+empty('배정된 학생이 없습니다.','학원에 학생 배정을 요청해 주세요.');return}if(student){const m=studentMetrics(childID()),next=hw.filter(h=>h.status==='missing'||h.status==='poor').sort((a,b)=>a.due_at.localeCompare(b.due_at));$('#main').innerHTML=head(`${esc(getStudent(childID()).name)} 학생의 클래스`,'차곡차곡 쌓이는 배움의 기록',btn('학습 리포트','navigate','data-view="reports"','','reports'))+context({view:false})+stats([['최근 시험',fmt(m.latest),'점','100점 환산'],['평균 성적',fmt(m.average),'점',m.count+'회 응시'],['과제 제출',m.submitted+'/'+m.homework,'건',m.missing?'기한이 지난 미제출 '+m.missing+'건':'제출 기록을 확인하세요',m.missing?'red':''],['나의 수업',S.base.classes.length,'개','지난 수강반 포함']])+section('지금 확인할 과제',lineHomework(next.slice(0,5)),btn('전체 보기','navigate','data-view="homework"','ghost sm','arrow'))+`<div class="split-view">${section('최근 수업',lineLessons([...S.data.lessons].sort((a,b)=>b.lesson_date.localeCompare(a.lesson_date)).slice(0,4)))}${section('선생님의 메시지',feedbackList(childID()))}</div>`;return}const reports=reportRows(),alerts=reports.filter(r=>r.matched),todayLessons=S.data.lessons.filter(l=>l.lesson_date===today()),upcoming=[...S.data.lessons].filter(l=>l.lesson_date>=today()).sort((a,b)=>a.lesson_date.localeCompare(b.lesson_date)).slice(0,4),requests=S.data.consultations.filter(c=>c.status==='requested');$('#main').innerHTML=head('오늘의 클래스','수업에 집중할 수 있도록, 필요한 기록만 한눈에.',btn('수업 입력','new-lesson','','primary','plus'))+context({view:false})+stats([['함께하는 학생',new Set(S.base.enrollments.filter(e=>(!S.classId||e.class_id===S.classId)&&e.status==='enrolled').map(e=>e.student_id)).size,'명',S.base.classes.filter(c=>c.status==='active').length+'개 운영 반'],['오늘의 수업',todayLessons.length,'개',todayLessons.length?'오늘의 수업 기록이 있습니다':'예정 수업을 등록해 주세요'],['확인할 과제',hw.filter(h=>h.status==='submitted').length,'건',hw.filter(h=>h.overdue).length+'건 기한 초과'],['상담 대기',requests.length,'건','학부모가 남긴 상담 신청']])+section(`우선 확인할 학생 <small>${alerts.length}명</small>`,alerts.length?simpleTable([{key:'name',label:'학생',render:r=>studentCell(r)},{key:'average',label:'평균',render:r=>fmt(r.average)+'점'},{key:'delta',label:'성적 추이',render:r=>spark(r.scored.map(x=>x.pct))},{key:'missing',label:'기한 초과',render:r=>r.missing?`<span class="red">${r.missing}건</span>`:'—'},{key:'reasons',label:'확인할 내용',render:r=>r.reasons.map(x=>badge('poor',x)).join(' ')},{key:'action',label:'',render:r=>btn('리포트','student-report',`data-id="${r.id}"`,'ghost sm','chevron')}],alerts.slice(0,5)):empty('현재 기준에 해당하는 학생이 없습니다.'),btn('기준 설정','navigate','data-view="reports"','ghost sm','filter'))+`<div class="split-view">${section('다가오는 수업',lineLessons(upcoming),btn('수업 전체','navigate','data-view="lessons"','ghost sm','arrow'))}${section('새 상담 신청',requests.length?`<div class="line-list">${requests.slice(0,4).map(c=>`<div class="notice-row"><div class="flex between"><strong style="font-size:12px">${esc(getStudent(c.student_id).name)}</strong><small>${dateText(c.created_at)}</small></div><p>${esc(c.reason.slice(0,65))}</p>${btn('내용 확인','consult-detail',`data-id="${c.id}"`,'ghost sm','chevron')}</div>`).join('')}</div>`:empty('새로운 상담 신청이 없습니다.'))}</div>`}
