function allFilteredRows(){let rows=rowsForView();const q=S.q.trim().toLowerCase();if(q)rows=rows.filter(r=>columnsFor().some(c=>String(c.plain?c.plain(r):r[c.key]??'').toLowerCase().includes(q)));if(S.filter)rows=rows.filter(r=>r.status===S.filter);const cols=columnsFor();if(S.sort.length)rows=[...rows].sort((a,b)=>{for(const {key,dir}of S.sort){const col=cols.find(c=>c.key===key);const aa=col?.plain?col.plain(a):a[key],bb=col?.plain?col.plain(b):b[key];let n;if(aa==null&&bb==null)n=0;else if(aa==null)n=1;else if(bb==null)n=-1;else n=typeof aa==='number'&&typeof bb==='number'?aa-bb:String(aa).localeCompare(String(bb),'ko',{numeric:true});if(n)return n*dir}return 0});return rows}
