function navigate(view){if(!accessibleNav().some(n=>n[0]===view))return;if(S.pending.size&&!confirm('저장하지 않은 셀 편집을 버리고 이동할까요?'))return;S.view=view;S.q='';S.filter='';S.selected.clear();S.sort=[];S.page=1;S.editing=false;S.pending.clear();S.undo=[];$('.sidebar')?.classList.remove('open');if(['parents','accounts','audit'].includes(view))reload();else render();window.scrollTo(0,0)}
