async function fetchPhotoBlob(id){if(DEMO){const a=D.attachments.find(x=>x.id===id);if(a?._blob)return a._blob;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1150;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,900,1150);ctx.fillStyle='#202b45';ctx.font='bold 35px sans-serif';ctx.fillText('과학 학습 기록 · 예시',70,90);ctx.font='23px sans-serif';['1. 물질의 상태 변화','고체 → 액체 : 융해','액체 → 기체 : 기화','','2. 열에너지의 출입','융해 · 기화 · 승화 : 열에너지 흡수','응고 · 액화 · 승화 : 열에너지 방출','','이 사진은 미리보기용 예시입니다.'].forEach((x,i)=>ctx.fillText(x,70,180+i*65));return new Promise(r=>canvas.toBlob(r,'image/jpeg',.8))}const access=await api('/api/files/'+id+'/access');let response;
if(access.direct){try{response=await fetch(access.url,{credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(30000)})}catch{response=null}}
if(!response?.ok)response=await fetch(C.API_URL.replace(/\/$/,'')+'/api/files/'+id,{headers:{Authorization:'Bearer '+S.token,...(isFamily()&&S.studentId?{'X-Student-ID':S.studentId}:{})},signal:AbortSignal.timeout(60000)});if(!response.ok){let d={};try{d=await response.json()}catch{}throw Error(d.detail||'사진을 가져오지 못했습니다.')}return response.blob()}
function loadPhotoThumbs(node,files,urls){
 files=files.filter(file=>{const image=$(`[data-photo-thumb="${file.id}"]`,node);return image&&!image.getAttribute('src')});
 let active=0,remaining=files.length;const queue=[];let observer,cleanupObserver;
 const run=()=>{while(active<3&&queue.length){const file=queue.shift();active++;
  photoBlob(file.id).then(blob=>{if(!node.isConnected)return;const url=URL.createObjectURL(blob);urls.push(url);const image=$(`[data-photo-thumb="${file.id}"]`,node);if(image)image.src=url})
  .catch(e=>{const image=$(`[data-photo-thumb="${file.id}"]`,node);if(image){image.alt=e.message;image.closest('button').title=e.message}})
  .finally(()=>{active--;remaining--;if(remaining<=0){observer?.disconnect();cleanupObserver?.disconnect()}run()});
 }};
 if(!files.length)return;
 if('IntersectionObserver' in window){
  const byId=new Map(files.map(f=>[f.id,f]));
  observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){observer.unobserve(entry.target);const f=byId.get(entry.target.dataset.photoThumb);if(f)queue.push(f)}run()},{rootMargin:'180px'});
  $$('[data-photo-thumb]',node).filter(image=>byId.has(image.dataset.photoThumb)).forEach(image=>observer.observe(image));
  cleanupObserver=new MutationObserver(()=>{if(!node.isConnected){observer.disconnect();cleanupObserver.disconnect();queue.length=0}});
  cleanupObserver.observe($('#modal-root'),{childList:true});
 }else{queue.push(...files);run()}
}
function homeworkDetail(id){const h=expectedHomework().find(x=>x.id===id);if(!h)return;let urls=[],currentFiles=[];const history=S.data.submissions.filter(s=>s.lesson_id===h.lesson.id&&s.student_id===h.student.id).sort((a,b)=>b.submitted_at.localeCompare(a.submitted_at));const canUpload=isFamily()&&S.base.enrollments.some(e=>e.class_id===h.lesson.class_id&&e.student_id===childID()&&e.status==='enrolled')&&getClass(h.lesson.class_id).status==='active';const late=new Date(h.due_at)<new Date(),staff=!isFamily();modal(h.title+' · '+h.student.name,`<div class="tagline">${badge(h.status)}<span>${esc(h.class_name)}</span></div><p class="preline">${esc(h.lesson.homework)}</p><div class="deadline ${late?'late':''}">${icon('clock')} ${timeText(h.due_at)}까지${late?'<strong>제출 기한이 지났습니다. 지각 제출이 가능합니다.</strong>':''}</div>${canUpload?`<div class="upload-zone" id="drop-zone"><div>${icon('camera',27)}<strong>과제 사진을 올려 주세요</strong><span>JPG · PNG · WebP / 최대 8장 / 사진 한 장당 12MB</span></div><div class="flex center wrap"><label class="btn primary">${icon('camera')}사진 촬영<input type="file" id="camera-input" accept="image/*" capture="environment" hidden></label><label class="btn">${icon('plus')}사진 선택<input type="file" id="photo-input" accept="image/jpeg,image/png,image/webp" multiple hidden></label></div></div><div id="upload-files"></div><div class="field"><label>과제와 함께 남길 말</label><textarea id="submission-note" maxlength="2000" rows="2"></textarea></div><div id="upload-progress" class="hidden"><div class="progress-track"><div id="upload-bar"></div></div><small id="upload-text"></small></div><div style="margin:14px 0">${btn(late?'기한 초과로 제출하기':'과제 제출하기','submit-photos','','primary','upload')}</div>`:''}<div class="form-section-title">제출 내역 · ${history.length}회</div>${history.length?history.map((s,i)=>{const files=S.data.attachments.filter(a=>a.submission_id===s.id);currentFiles.push(...files);return`<section class="submission-history"><div class="flex between wrap"><strong>${timeText(s.submitted_at)}</strong><div>${badge(s.status)} ${s.late?badge('poor','지각 제출'):''}${i===0?'<span class="badge">최근 제출</span>':''}</div></div>${s.note?`<p class="preline">${esc(s.note)}</p>`:''}<div class="photo-strip">${files.map((f,n)=>`<button class="photo-thumb" type="button" data-action="view-photo" data-id="${f.id}"><img data-photo-thumb="${f.id}" alt="${esc(f.name)}" loading="lazy"><span>${n+1}</span></button>`).join('')}</div>${s.feedback?`<div class="review-message"><strong>선생님의 확인</strong><p class="preline">${esc(s.feedback)}</p></div>`:''}${staff?btn('상태 · 피드백 변경','review-submission',`data-id="${s.id}"`,'sm','edit'):''}</section>`}).join(''):empty('아직 제출한 사진이 없습니다.')}`, '',{wide:true,cleanup:()=>urls.forEach(x=>URL.revokeObjectURL(x))});const node=M.node;node._resumePhotos=()=>loadPhotoThumbs(node,currentFiles,urls);node._resumePhotos();if(!canUpload)return;let queue=[],requestId=uid(),busy=false;const draw=()=>{$('#upload-files',node).innerHTML=queue.map((f,i)=>`<div class="file-row"><span>${icon('file')} ${esc(f.name)}</span><span>${fmt(f.size/1024,0)} KB ${ib('close','remove-upload',`data-index="${i}"`,'사진 제거')}</span></div>`).join('');$$('[data-action=remove-upload]',node).forEach(x=>x.onclick=()=>{if(busy)return;queue.splice(+x.dataset.index,1);requestId=uid();draw()})};const add=files=>{if(busy)return;for(const f of files){if(queue.length>=8){toast('한 번에 8장까지 제출할 수 있습니다.',true);break}if(f.size>12*1024*1024){toast(f.name+': 한 장당 12MB 이하로 선택해 주세요.',true);continue}if(!/^image\//.test(f.type)){toast('이미지 파일만 선택해 주세요.',true);continue}queue.push(f)}requestId=uid();M.dirty=true;draw()};$('#photo-input',node).onchange=e=>add(e.target.files);$('#camera-input',node).onchange=e=>add(e.target.files);const dz=$('#drop-zone',node);dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag-over')};dz.ondragleave=()=>dz.classList.remove('drag-over');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag-over');add(e.dataTransfer.files)};const upload=$('[data-action=submit-photos]',node);upload.onclick=async()=>{if(!queue.length)return errorBox('제출할 사진을 선택해 주세요.');if(queue.reduce((n,f)=>n+f.size,0)>25*1024*1024)return errorBox('한 번에 25MB 이하로 제출해 주세요.');busy=true;upload.disabled=true;$('#upload-progress',node).classList.remove('hidden');try{const form=new FormData();form.append('request_id',requestId);form.append('note',$('#submission-note',node).value);for(const file of queue)form.append('files',file,file.name);await sendPhotos(h.lesson.id,form,p=>{$('#upload-bar',node).style.width=p+'%';$('#upload-text',node).textContent=p<100?'업로드 중 · '+Math.floor(p)+'%':'사진을 저장하고 있습니다…'});closeModal(true);await reload();toast('과제를 제출했습니다.')}catch(e){errorBox(e.message)}finally{busy=false;upload.disabled=false}}}
function sendPhotos(lessonId,form,progress){if(DEMO){progress(100);return demoUpload(lessonId,form)}return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',C.API_URL.replace(/\/$/,'')+'/api/homework/'+lessonId);xhr.setRequestHeader('Authorization','Bearer '+S.token);if(isFamily()&&S.studentId)xhr.setRequestHeader('X-Student-ID',S.studentId);xhr.timeout=180000;xhr.upload.onprogress=e=>{if(e.lengthComputable)progress(e.loaded/e.total*100)};xhr.onload=()=>{let d={};try{d=JSON.parse(xhr.responseText)}catch{}if(xhr.status>=200&&xhr.status<300)resolve(d);else reject(new Error(d.detail||'제출하지 못했습니다. 다시 시도해 주세요.'))};xhr.onerror=()=>reject(new Error('연결이 끊어졌습니다. 같은 사진으로 다시 제출하면 중복 저장을 확인합니다.'));xhr.ontimeout=()=>reject(new Error('응답이 늦어지고 있습니다. 제출함을 새로고침해 확인 후 다시 시도해 주세요.'));xhr.send(form)})}
