  if(!link.isConnected)return;easyPC.checkId=r.id;easyPC.owner=S.user.id;easyPC.status={state:'waiting',confirmed:false,online:false};
  if(DEMO){link.href='#';link.dataset.previewLink='1'}else{
   const q=new URLSearchParams({api:C.API_URL.replace(/\/$/,''),challenge:r.challenge});if(r.code){q.set('code',r.code);q.set('device',r.device_id)}
   link.href='miraeclassroom://'+purpose+'?'+q.toString();delete link.dataset.previewLink;
  }
  link.removeAttribute('aria-disabled');link.textContent=purpose==='connect'?'연결 프로그램 열고 이 PC 연결':'연결 프로그램 열고 실행 확인';drawPCWizard();watchEasyPC();
