async function loadDirectory(){
 const token=S.token,stamp=S.base.timenet_meta?.updated_at||'';
 if(directoryCache?.token===token&&directoryCache.stamp===stamp)return directoryCache.promise;
 const entry={token,stamp,promise:null};entry.promise=api('/api/timenet/directory').then(result=>(result.rows||[]).map(row=>({...row,_search:[row.name,row.student_no,row.school,...(row.classes||[]).map(c=>c.name||'')].join(' ').normalize('NFKC').toLocaleLowerCase('ko-KR')})));
 directoryCache=entry;try{return await entry.promise}catch(error){if(directoryCache===entry)directoryCache=null;throw error}
}
function rosterPicker(){
 let rows=[],ready=false;modal('타임넷 학생 선택',`<div class="search-wrap roster-search">${icon('search')}<input class="input" id="roster-query" placeholder="학생명 · 원생번호 · 학교 · 반" autocomplete="off"></div><div class="flex between" style="margin:12px 0"><small>마지막 갱신 · ${age(S.base.timenet_meta?.updated_at)}</small>${btn('다시 불러오기','timenet-refresh','','ghost sm','refresh')}</div><div id="roster-results">${empty('저장된 명단을 가져오고 있습니다.')}</div>`,'',{wide:true});
 const node=M.node;
 function draw(){if(!node.isConnected||!ready)return;const q=$('#roster-query',node).value.trim().normalize('NFKC').toLocaleLowerCase('ko-KR');
  if(!q){$('#roster-results',node).innerHTML=empty(rows.length?'학생명 또는 원생번호를 입력해 주세요.':'저장된 명단이 없습니다. 학생 목록을 먼저 불러와 주세요.');return}
  const matches=rows.filter(row=>row._search.includes(q));const shown=matches.slice(0,100);
  $('#roster-results',node).innerHTML=shown.length?`<small class="muted">${matches.length.toLocaleString()}명${matches.length>100?' · 앞 100명 표시':''}</small><div class="line-list">${shown.map(row=>`<button class="choice-row" data-roster="${esc(row.student_no)}"><span class="avatar">${esc(row.name.slice(-2))}</span><span class="grow"><strong>${esc(row.name)} <small>${esc(row.student_no)}</small></strong><span>${esc(row.school)} ${esc(row.grade)}</span><small>${esc((row.classes||[]).map(c=>typeof c==='string'?c:c.name||c.class_name).join(' · '))}</small></span>${icon('chevron')}</button>`).join('')}</div>`:empty('일치하는 학생이 없습니다.');
  $$('[data-roster]',node).forEach(button=>button.onclick=()=>enrollRoster(shown.find(row=>row.student_no===button.dataset.roster)));
 }
 $('#roster-query',node).oninput=draw;
 loadDirectory().then(data=>{rows=data;ready=true;draw()}).catch(error=>{if(node.isConnected)$('#roster-results',node).innerHTML=`<div class="alert error">${esc(error.message)}</div>`});
}
function enrollRoster(s){modal(s.name+' · 학생 등록',`<div class="tagline"><span class="badge">원생번호 ${esc(s.student_no)}</span><span>${esc(s.school)} ${esc(s.grade)}</span></div><p class="muted">${esc((s.classes||[]).map(c=>typeof c==='string'?c:c.name||c.class_name).join(' · '))}</p><form id="roster-enroll">${fieldsHtml([{key:'class_id',label:'등록할 수강반',type:'select',options:classOptions(),default:currentClass(),wide:true,required:true},{key:'joined_on',label:'수강 시작일',type:'date',default:today(),required:true}])}</form>`,btn('선택한 학생 등록','save-editor','','primary','check'));M.save=async()=>{if(!$('#roster-enroll').reportValidity())return;try{await api('/api/timenet/enroll',{method:'POST',body:{rows:[{student_no:s.student_no,...collect()}]}});closeAll();await reload(true);toast(s.name+' 학생을 등록했습니다.')}catch(e){errorBox(e.message)}}}
function commandPalette(){modal('빠른 이동',`<input class="input" id="command-input" placeholder="화면 · 학생 · 반 검색" autocomplete="off"><div id="command-results"></div>`, '',{wide:false});const node=M.node;function draw(){const q=$('#command-input',node).value.trim().toLowerCase();let html=accessibleNav().filter(([,l])=>l.toLowerCase().includes(q)).map(([k,l,ic])=>`<button class="command-item" data-command-view="${k}">${icon(ic)}<strong>${l}</strong><span class="grow"></span><kbd>↵</kbd></button>`).join('');if(q&&!isFamily())html+=S.base.students.filter(s=>[s.name,s.school,s.student_no].join(' ').toLowerCase().includes(q)).slice(0,12).map(s=>`<button class="command-item" data-command-student="${s.id}">${icon('students')}<span>${esc(s.name)}<small>${esc(s.student_no)} · ${esc(s.school)}</small></span></button>`).join('');$('#command-results',node).innerHTML=html;$$('[data-command-view]',node).forEach(x=>x.onclick=()=>{closeModal(true);navigate(x.dataset.commandView)});$$('[data-command-student]',node).forEach(x=>x.onclick=()=>{closeModal(true);studentDetail(x.dataset.commandStudent)})}$('#command-input',node).oninput=draw;$('#command-input',node).onkeydown=e=>{if(e.key==='Enter')$('#command-results button',node)?.click();if(e.key==='ArrowDown'){$('#command-results button',node)?.focus();e.preventDefault()}};draw()}
