const DEFAULT_DESIGN={academy_name:C.BRAND||'미래탐구',eyebrow:'LEARNING, CONNECTED.',headline:'배움의 순간이\n성장의 기록으로.',description:'수업과 과제, 성적의 변화까지.\n매일의 배움을 함께 살펴보는 공간입니다.',form_title:'클래스룸 로그인',form_subtitle:'오늘의 배움을 이어가세요.',footer:'접속이 어려운 경우 담당 선생님께 문의해 주세요.',accent:'sage',alignment:'left',layout:'split'};
