function safeDesign(raw={}){const out={...DEFAULT_DESIGN};for(const k of ['academy_name','eyebrow','headline','description','form_title','form_subtitle','footer'])if(typeof raw[k]==='string')out[k]=raw[k].slice(0,240);for(const [k,allowed]of Object.entries({accent:['sage','blue','ink','sand'],alignment:['left','center'],layout:['split','center']}))if(allowed.includes(raw[k]))out[k]=raw[k];return out}
