async function renderLoginSettings(){const node=$('#main');node.innerHTML=head('로그인 화면','학원에 맞는 문구와 분위기를 설정합니다.')+`<div class="design-editor-loading">설정을 가져오고 있습니다.</div>`;try{const result=await api('/api/admin/login-design');if(!node.isConnected||S.view!=='appearance')return;let draft=safeDesign(result.design),revision=result.revision||'';const textFields=[['academy_name','학원명',40],['eyebrow','상단 짧은 문구',70],['headline','대표 문구',100],['description','소개 문구',240],['form_title','로그인 제목',50],['form_subtitle','로그인 부제목',100],['footer','하단 안내',160]].map(([key,label,maxlength])=>({key,label,maxlength,wide:true,type:['headline','description'].includes(key)?'textarea':'text',rows:2}));node.innerHTML=head('로그인 화면','저장한 문구는 모든 접속자에게 동일하게 적용됩니다.',btn('기본 문구','design-reset','','','undo')+btn('변경 저장','design-save','','primary','check'))+`<div class="design-editor"><form id="design-form" class="design-controls">${fieldsHtml([...textFields,{key:'accent',label:'색상',type:'select',options:[['sage','세이지 · 차분한 녹색'],['blue','미스트 · 부드러운 파랑'],['ink','잉크 · 깊은 회청색'],['sand','샌드 · 따뜻한 베이지']]},{key:'alignment',label:'문구 정렬',type:'select',options:[['left','왼쪽'],['center','가운데']]},{key:'layout',label:'배치',type:'select',wide:true,options:[['split','문구와 로그인 나란히'],['center','로그인 중심']]}],draft)}</form><section class="design-live"><div class="design-live-label"><span class="signal on"></span>미리보기 <small>저장 전에는 운영 화면에 반영되지 않습니다.</small></div><div id="design-live-canvas"></div><div id="design-save-status" role="status" aria-live="polite"></div></section></div>`;const form=$('#design-form');form.onsubmit=e=>e.preventDefault();function draw(){draft=safeDesign(collect(form));const canvas=$('#design-live-canvas');canvas.dataset.tone=draft.accent;canvas.innerHTML=loginMarkup(draft,true);fitLoginPreview(canvas);$$('input,button',canvas).forEach(x=>{x.tabIndex=-1;x.disabled=true})}form.addEventListener('input',draw);form.addEventListener('change',draw);draw();$('[data-action=design-reset]',node).onclick=()=>{for(const k of Object.keys(DEFAULT_DESIGN)){const x=form.elements.namedItem(k);if(x)x.value=DEFAULT_DESIGN[k]}draw()};$('[data-action=design-save]',node).onclick=async()=>{const button=$('[data-action=design-save]',node);if(button.disabled)return;button.disabled=true;button.setAttribute('aria-busy','true');try{const r=await api('/api/admin/login-design',{method:'POST',body:{design:draft,revision}});revision=r.revision;loginDesign=safeDesign(r.design);designRevision=revision;themeDesign();$('#design-save-status').textContent='로그인 화면에 적용했습니다.';toast('로그인 화면을 저장했습니다.')}catch(e){$('#design-save-status').textContent=e.message;toast(e.message,true)}finally{button.disabled=false;button.removeAttribute('aria-busy')}}}catch(e){if(node.isConnected)node.innerHTML=head('로그인 화면')+`<div class="alert error">${esc(e.message)}</div>`}}

// Direct proof from THIS Windows machine; no "last online PC" inference.
function isMobileClient(){return !!navigator.userAgentData?.mobile||/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent)||(/Mac/.test(navigator.platform)&&navigator.maxTouchPoints>1)}
function canUsePC(){return !isMobileClient()&&(DEMO||/Windows|Win32|Win64/i.test(navigator.userAgent+' '+navigator.platform))}
let presence={timer:null,owner:'',ticket:'',ticketUntil:0,goodUntil:0,lastChecked:0,promise:null,controller:null,generation:0,permissionNeeded:false};
function stopPresence(){if(presence.timer)clearInterval(presence.timer);presence.controller?.abort();presence={timer:null,owner:'',ticket:'',ticketUntil:0,goodUntil:0,lastChecked:0,promise:null,controller:null,generation:presence.generation+1,permissionNeeded:false}}
function paintPCStatus(){document.body.classList.toggle('pc-mobile',!canUsePC());updatePCIndicator()}
function localReady(){return canUsePC()&&easyPC.owner===S.user?.id&&easyPC.status?.local_verified&&easyPC.status?.online&&presence.goodUntil>Date.now()&&!pcNeedsUpdate()}
async function probeThisPC(force=false){
 if(!canUsePC()||!S.user||isFamily()||document.hidden)return false;
 if(DEMO){if(!easyPC.status?.confirmed){easyPC.owner=S.user.id;easyPC.status={confirmed:false,online:false,state:'unpaired'}}paintPCStatus();return !!easyPC.status?.online}
 if(presence.promise)return presence.promise;
 const generation=presence.generation,owner=S.user.id;presence.owner=owner;
 presence.promise=(async()=>{
  try{
   try{const permission=await navigator.permissions?.query({name:'local-network-access'});if(permission?.state==='denied'||(!force&&permission?.state==='prompt')){presence.permissionNeeded=true;throw Error('permission')}}catch(e){if(e.message==='permission')throw e}
   presence.permissionNeeded=false;
   if(!presence.ticket||presence.ticketUntil<Date.now()){
    const t=await api('/api/pc/easy/probe-ticket',{method:'POST',body:{},signal:AbortSignal.timeout(8000)});
    if(generation!==presence.generation||S.user?.id!==owner)return false;
    presence.ticket=t.ticket;presence.ticketUntil=Date.now()+Math.max(10,t.expires_in-15)*1000;
   }
   const nonce=uid().replaceAll('-','')+uid().slice(0,8);const controller=new AbortController();presence.controller=controller;const timeout=setTimeout(()=>controller.abort(),9500);
   let result;
   try{result=await fetch('http://127.0.0.1:17843/mirae/v1/presence',{method:'POST',mode:'cors',credentials:'omit',cache:'no-store',headers:{'Content-Type':'application/json','X-Mirae-Probe':'1'},body:JSON.stringify({api:C.API_URL.replace(/\/$/,''),ticket:presence.ticket,nonce}),signal:controller.signal})}finally{clearTimeout(timeout);presence.controller=null}
   if(!result.ok)throw Error('not-connected');const local=await result.json();
   const d=await api('/api/pc/easy/probe-verify',{method:'POST',body:{proof:local.proof,nonce},signal:AbortSignal.timeout(8000)});
   if(generation!==presence.generation||S.user?.id!==owner)return false;
   easyPC.owner=owner;easyPC.status=d;presence.goodUntil=Date.now()+Math.min(d.expires_in||20,35)*1000;presence.lastChecked=Date.now();paintPCStatus();drawPCWizard();if($('#pc-panel'))renderPCPanel(false);return d.online&&!pcNeedsUpdate(d);
  }catch(error){
   if(generation!==presence.generation||S.user?.id!==owner)return false;
   presence.goodUntil=0;presence.lastChecked=Date.now();
   // An explicitly launched, same-page URI check remains a supported fallback
   // where browser local-network access is blocked. It is not inferred from IP.
   if(easyPC.checkId){await pollEasyPC();if(easyPC.status?.confirmed&&easyPC.status?.online&&!pcNeedsUpdate())return true}
   easyPC.owner=owner;easyPC.status={confirmed:false,online:false,state:'unpaired',message:presence.permissionNeeded?'이 사이트의 PC 자동 확인을 허용해 주세요.':'연결 프로그램 실행 또는 연결 확인이 필요합니다.'};paintPCStatus();return false;
  }finally{if(generation===presence.generation){presence.promise=null;presence.controller=null}}
 })();return presence.promise;
}
function startPresence(){paintPCStatus();loadPCRelease();if(S.loading&&!presence.timer)return;if(!canUsePC()||!S.user||isFamily()){stopPresence();return}if(presence.timer&&presence.owner===S.user.id)return;stopPresence();presence.owner=S.user.id;easyPC.owner=S.user.id;probeThisPC();presence.timer=setInterval(()=>{if(!document.hidden){loadPCRelease();probeThisPC()}},15000)}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){paintPCStatus();probeThisPC()}});window.addEventListener('online',()=>probeThisPC());window.addEventListener('pagehide',()=>stopPresence());

let timenetTask=null;
function syncMarkup(task){return `<div class="sync-screen sync-modern" role="status" aria-live="polite"><div class="sync-stage" aria-hidden="true"><div class="sync-matrix"></div><div class="sync-path"><span></span><span></span><span></span></div><div class="sync-core">${mark}<i></i><i></i></div><div class="sync-dots">${Array.from({length:7},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div></div><div class="eyebrow">CONNECTED TO YOUR CLASSROOM</div><h3>${task.kind==='check_sheet'?'스프레드시트 연결을 확인하고 있습니다.':'타임넷 학생 정보를 불러오고 있습니다.'}</h3><p class="pc-route">${esc(task.pc.name||'이 PC')}<span>·</span>${task.kind==='check_sheet'?'GOOGLE SHEETS':'TIMENET'}<span>·</span>CLASSROOM</p><p id="sync-message">연결한 PC에 요청을 전달합니다.</p><small class="sync-duration">수 분의 시간이 소요될 수 있습니다.</small><div id="sync-events"></div></div>`}
function showSyncTask(task){modal(task.kind==='check_sheet'?'시트 연결 확인':'타임넷 학생 목록',syncMarkup(task),btn('창 닫기','close-modal')+btn('갱신 취소','pc-cancel','','ghost'),{cleanup:()=>{task.node=null}});task.node=M.node;M.cancelPC=async()=>{if(!task.id||task.terminal||DEMO)return;drawSyncTask(task,await api('/api/pc/jobs/'+task.id+'/cancel',{method:'POST'}))};if(task.last)drawSyncTask(task,task.last)}
function drawSyncTask(task,j){task.last=j;const failed=['error','cancelled'].includes(j.state);if(failed||j.state==='done')task.terminal=true;const node=task.node;if(!node?.isConnected)return;$('#sync-message',node).textContent=j.message||'';if(task.terminal){$('.modal-footer',node).innerHTML=btn('닫기','close-modal')+(j.state==='done'&&task.kind==='roster'?btn('학생 등록하기','roster-picker','','primary','students'):'');const screen=$('.sync-screen',node);screen.classList.remove('sync-error','sync-done');screen.classList.add(failed?'sync-error':'sync-done');$('h3',node).textContent=failed?(j.state==='cancelled'?'갱신을 취소했습니다.':'학생 정보를 가져오지 못했습니다.'):(task.kind==='roster'?'학생 목록을 불러왔습니다.':'시트 연결을 확인했습니다.');$('#sync-events',node).textContent=failed?'마지막으로 성공한 학생 목록은 유지됩니다.':'';$('.sync-duration',node).hidden=true}}
async function refreshTimenetModern(kind='roster'){
 if(!canUsePC())return;
 if(timenetTask&&!timenetTask.terminal&&timenetTask.owner===S.user?.id){showSyncTask(timenetTask);return}
 const pc=await requirePC(kind);if(!pc)return;
 const task={id:'',owner:S.user.id,kind,pc,node:null,terminal:false,last:null};timenetTask=task;showSyncTask(task);
 try{
  if(DEMO){for(const j of [{state:'running',message:'미리보기 · 연결한 PC에서 조회 요청을 준비합니다.'},{state:'running',message:'미리보기 · 학생 정보와 수강반을 확인합니다.'},{state:'done',message:'미리보기 · 실제 타임넷에는 접속하지 않습니다.'}]){await new Promise(r=>setTimeout(r,650));drawSyncTask(task,j)}if(kind==='roster')D.timenet_meta={updated_at:new Date().toISOString(),count:D.roster.length,source_device_name:pc.name}}
  else{
   const j=await api(kind==='check_sheet'?'/api/timenet/check-sheet':'/api/timenet/refresh',{method:'POST',body:{device_id:pc.id}});task.id=j.id;drawSyncTask(task,j);
   while(!task.terminal&&task.owner===S.user?.id){await new Promise(r=>setTimeout(r,task.node?1000:3500));if(task.owner!==S.user?.id)break;drawSyncTask(task,await api('/api/pc/jobs/'+task.id))}
  }
  if(task.terminal&&kind==='roster'&&task.owner===S.user?.id){directoryCache=null;S.base.timenet_meta=await api('/api/timenet/meta');const ageNode=$('#cache-age');if(ageNode)ageNode.textContent='· '+age(S.base.timenet_meta.updated_at);if(!task.node)toast(task.last.state==='done'?'타임넷 학생 목록을 갱신했습니다.':'타임넷 조회를 완료하지 못했습니다.',task.last.state!=='done')}
 }catch(e){if(task.owner===S.user?.id)drawSyncTask(task,{state:'error',message:e.message})}
}

